{"code": "
async def game_call(tool_name, **kwargs):
    """Call a nethack tool with retry on timeout."""
    for attempt in range(5):
        try:
            result = await nethack.call_tool(tool_name, kwargs if kwargs else None)
            return result
        except Exception as e:
            print(f"  Attempt {attempt+1} failed: {type(e).__name__}")
            if attempt < 4:
                await asyncio.sleep(10)
    return None

# Test it - check current state
result = await game_call('np_look')
if result:
    print(result)
"}

